practice.solution:
export abstract class PriceRule {
  abstract applies(cents: number): boolean;
  abstract apply(cents: number): number;

  run(cents: number): number {
    return this.applies(cents) ? this.apply(cents) : cents;
  }
}

export class BulkDiscount extends PriceRule {
  minCents: number;
  percent: number;

  constructor(minCents: number, percent: number) {
    super();
    this.minCents = minCents;
    this.percent = percent;
  }

  applies(cents: number): boolean {
    return cents >= this.minCents;
  }

  apply(cents: number): number {
    return Math.round(cents * (1 - this.percent / 100));
  }
}

export class MinimumCharge extends PriceRule {
  minimumCents: number;

  constructor(minimumCents: number) {
    super();
    this.minimumCents = minimumCents;
  }

  applies(cents: number): boolean {
    return cents < this.minimumCents;
  }

  apply(): number {
    return this.minimumCents;
  }
}

const bulk = new BulkDiscount(10000, 10);
const minimum = new MinimumCharge(500);
console.log(`bulk 12000 -> ${bulk.run(12000)}`);
console.log(`bulk 8000 -> ${bulk.run(8000)}`);
console.log(`minimum 300 -> ${minimum.run(300)}`);
console.log(`minimum 900 -> ${minimum.run(900)}`);

tests.append:
const small = new MinimumCharge(250);
console.log(`${small.run(100)} ${small.run(250)} ${small.run(1000)}`);
const half = new BulkDiscount(2000, 50);
console.log(`${half.run(1999)} ${half.run(3000)}`);

steps.body:
A class that creates its own dependencies is hard to test and hard to change. If an `OrderService` opens its own database and reads the system clock, every run needs that database and prints a different time. Instead, describe each dependency with an interface, and let the constructor receive it:

```typescript
interface Clock {
  now(): Date;
}

class Greeter {
  #clock: Clock;

  constructor(clock: Clock) {
    this.#clock = clock;
  }

  greeting(): string {
    return this.#clock.now().getUTCHours() < 12 ? "Good morning" : "Good afternoon";
  }
}

const morning: Clock = { now: () => new Date("2026-10-01T09:00:00Z") };
console.log(new Greeter(morning).greeting()); // Good morning
```

The class keeps what it receives in a field and only calls the interface's methods. In production you pass the real thing, like a SQLite repository or a clock that reads the time. In a test or an example you pass a `Map`, a clock that never moves, or a fake that records what happened. This is dependency injection. It needs no framework, only a constructor, with the fields written out because parameter properties aren't erasable.

examples.code:
type Order = { id: string; customer: string; totalCents: number };

interface OrderRepository {
  save(order: Order): void;
  find(id: string): Order | undefined;
  all(): Order[];
}

class InMemoryOrderRepository implements OrderRepository {
  #orders = new Map<string, Order>();

  save(order: Order): void {
    this.#orders.set(order.id, order);
  }

  find(id: string): Order | undefined {
    return this.#orders.get(id);
  }

  all(): Order[] {
    return [...this.#orders.values()];
  }
}

class OrderService {
  #orders: OrderRepository;
  #nextNumber = 1;

  constructor(orders: OrderRepository) {
    this.#orders = orders;
  }

  place(customer: string, totalCents: number): Order {
    const order = { id: `ord_${this.#nextNumber}`, customer, totalCents };
    this.#nextNumber += 1;
    this.#orders.save(order);
    return order;
  }

  revenueCents(): number {
    return this.#orders.all().reduce((sum, order) => sum + order.totalCents, 0);
  }
}

const repository = new InMemoryOrderRepository();
const service = new OrderService(repository);
service.place("Ada", 1299);
service.place("Ben", 450);
console.log(`Revenue: ${service.revenueCents()} cents`);
console.log(`ord_2 is for ${repository.find("ord_2")?.customer ?? "nobody"}`);
console.log(`ord_9 is for ${repository.find("ord_9")?.customer ?? "nobody"}`);

interface Clock {
  now(): Date;
}

const systemClock: Clock = { now: () => new Date() };

function fixedClock(iso: string): Clock {
  const instant = new Date(iso);
  return { now: () => instant };
}

class InvoiceService {
  #clock: Clock;

  constructor(clock: Clock) {
    this.#clock = clock;
  }

  issue(customer: string, totalCents: number): string {
    const issued = this.#clock.now();
    const due = new Date(issued.getTime() + 14 * 24 * 60 * 60 * 1000);
    const day = (date: Date) => date.toISOString().slice(0, 10);
    return `${customer}: $${(totalCents / 100).toFixed(2)}, issued ${day(issued)}, due ${day(due)}`;
  }
}

const october = new InvoiceService(fixedClock("2026-10-01T09:00:00Z"));
const december = new InvoiceService(fixedClock("2026-12-24T18:30:00Z"));
console.log(october.issue("Ada", 12900));
console.log(december.issue("Ben", 4500));

type Order = { id: string; email: string; totalCents: number };

interface Mailer {
  send(to: string, subject: string): void;
}

class FakeMailer implements Mailer {
  sent: { to: string; subject: string }[] = [];

  send(to: string, subject: string): void {
    this.sent.push({ to, subject });
  }
}

class CheckoutService {
  #mailer: Mailer;

  constructor(mailer: Mailer) {
    this.#mailer = mailer;
  }

  complete(order: Order): void {
    this.#mailer.send(order.email, `Order ${order.id} confirmed`);
    if (order.totalCents >= 10000) {
      this.#mailer.send("sales@example.com", `Large order ${order.id}`);
    }
  }
}

const mailer = new FakeMailer();
const checkout = new CheckoutService(mailer);
checkout.complete({ id: "ord_1", email: "ada@example.com", totalCents: 2500 });
checkout.complete({ id: "ord_2", email: "ben@example.com", totalCents: 18000 });

console.log(`${mailer.sent.length} emails`);
for (const mail of mailer.sent) {
  console.log(`${mail.to}: ${mail.subject}`);
}

