practice.solution:
export interface RateProvider {
  rate(from: string, to: string): number | undefined;
}

export class FixedRateProvider implements RateProvider {
  #rates: Record<string, number>;

  constructor(rates: Record<string, number>) {
    this.#rates = rates;
  }

  rate(from: string, to: string): number | undefined {
    return this.#rates[`${from}->${to}`];
  }
}

export class PriceService {
  #rates: RateProvider;

  constructor(rates: RateProvider) {
    this.#rates = rates;
  }

  convert(cents: number, from: string, to: string): string {
    const rate = this.#rates.rate(from, to);
    if (rate === undefined) {
      return `no rate for ${from}->${to}`;
    }
    const converted = Math.round(cents * rate);
    return `${(cents / 100).toFixed(2)} ${from} = ${(converted / 100).toFixed(2)} ${to}`;
  }
}

const rates = new FixedRateProvider({ "USD->EUR": 0.92, "EUR->GBP": 0.86 });
const prices = new PriceService(rates);
console.log(prices.convert(2500, "USD", "EUR"));
console.log(prices.convert(1000, "EUR", "GBP"));
console.log(prices.convert(500, "GBP", "JPY"));

